import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// --- Google Fonts Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// --- End Google Fonts Loader ---



export type ThreeDepthBarrierProps = Record<string, any>;

const ThreeDepthBarrier: React.FC<ThreeDepthBarrierProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = true,
  durationInSeconds = 5,
  mainText = "3",
  primaryColor = "#ffffff",
  depthColor = "#4a4a4a",
  fontSize = 600,
  spread = 40,
}) => {
  // Use "Outfit" as a geometric sans-serif alternative to TT Chocolates
  useFontLoader(["Outfit"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color Handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Constants
  const entranceDelay = 5;
  
  // Base Spring
  const baseSpring = spring({
    frame: frame - entranceDelay,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
      mass: 0.8,
    },
  });

  // Derived Animations
  const mainScale = interpolate(baseSpring, [0, 1], [0.8, 1]);
  const mainOpacity = interpolate(baseSpring, [0, 1], [0, 1]);

  // Depth Layers (Staggered appearance)
  // Layer 2 (Middle)
  const layer2Spring = spring({
    frame: frame - entranceDelay - 5,
    fps,
    config: { damping: 14, stiffness: 80 },
  });
  
  // Layer 3 (Back)
  const layer3Spring = spring({
    frame: frame - entranceDelay - 10,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  // Calculate offsets for "Structured Barrier" look
  // We offset them slightly on X and Y to create a pseudo-3D stack
  const layer2X = interpolate(layer2Spring, [0, 1], [0, spread * 0.8]);
  const layer2Y = interpolate(layer2Spring, [0, 1], [0, -spread * 0.6]);
  
  const layer3X = interpolate(layer3Spring, [0, 1], [0, spread * 1.6]);
  const layer3Y = interpolate(layer3Spring, [0, 1], [0, -spread * 1.2]);

  const baseTextStyle: React.CSSProperties = {
    fontFamily: "Outfit",
    fontWeight: 700,
    fontSize: fontSize,
    lineHeight: 1,
    position: "absolute",
    top: "50%",
    left: "50%",
    transform: "translate(-50%, -50%)",
    margin: 0,
    padding: 0,
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Container for centering and global movement if needed */}
      <div 
        style={{ 
          position: "relative", 
          width: "100%", 
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center"
        }}
      >
        {/* Layer 3: Deepest Background */}
        <h1
          style={{
            ...baseTextStyle,
            color: depthColor,
            opacity: interpolate(layer3Spring, [0, 1], [0, 0.3]),
            transform: `translate(calc(-50% + ${layer3X}px), calc(-50% + ${layer3Y}px)) scale(${interpolate(layer3Spring, [0, 1], [0.8, 0.85])})`,
            zIndex: 1,
          }}
        >
          {mainText}
        </h1>

        {/* Layer 2: Middle Background */}
        <h1
          style={{
            ...baseTextStyle,
            color: depthColor,
            opacity: interpolate(layer2Spring, [0, 1], [0, 0.6]),
            transform: `translate(calc(-50% + ${layer2X}px), calc(-50% + ${layer2Y}px)) scale(${interpolate(layer2Spring, [0, 1], [0.8, 0.92])})`,
            zIndex: 2,
          }}
        >
          {mainText}
        </h1>

        {/* Layer 1: Foreground Main */}
        <h1
          style={{
            ...baseTextStyle,
            color: primaryColor,
            opacity: mainOpacity,
            transform: `translate(-50%, -50%) scale(${mainScale})`,
            zIndex: 3,
            textShadow: `0px 10px 30px ${depthColor}40`, // Soft drop shadow for grounding
          }}
        >
          {mainText}
        </h1>
      </div>
    </AbsoluteFill>
  );
};

export default ThreeDepthBarrier;